import React from 'react';
import './Ended.css'; // Ujistěte se, že máte tento soubor pro stylování komponenty



const Home = (onReturnToApp ) => {
  return (
    <div className="ended">
      <h2>Game Over!</h2>
      <div className="buttons">
        <button onClick={onNewGame}>New Game</button> {/* Tlačítko pro novou hru */}
        <button onClick={onReturnToApp}>Return to Main Screen</button> {/* Correct button */}      </div>
    </div>
  );
};

export default Home;
